using AsyncScapeIA.Domain;using TUnit;using TUnit.Assertions;namespace AsyncScapeIA.UnitTests.Domain;public class SchemaDocumentTests{    [Test]    public async Task MatchesChecksum_returns_true_for_identical_checksum()    {        var document = SchemaDocument.Create(            name: "Payments",            format: SchemaFormat.OpenApi,            version: "1.0.0",            checksum: "sha256::abc123");        await Assert.That(document.MatchesChecksum("sha256::abc123"))            .IsTrue();    }}